import sys
import pandas as pd
import numpy as np
import json

# Read CSV
df = pd.read_csv(sys.argv[1])

facts = []

# Helper function to convert numpy types to Python types
def to_python(val):
    if pd.isna(val):
        return None
    if isinstance(val, (np.integer, np.floating)):
        return float(val)
    return val

# 1. Top entities by Revenue_TW (Rank 1, 2, 3)
top_entities = df.nlargest(3, 'Revenue_TW')
for idx, row in top_entities.iterrows():
    if pd.notna(row['Revenue_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "revenue",
            "period": "TW",
            "value": round(to_python(row['Revenue_TW']), 2),
            "formula": "Revenue_TW"
        })

# 2. Total Revenue_TW
total_rev_tw = df['Revenue_TW'].sum()
if pd.notna(total_rev_tw) and total_rev_tw > 0:
    facts.append({
        "entity": "TOTAL",
        "metric": "revenue",
        "period": "TW",
        "value": round(to_python(total_rev_tw), 2),
        "formula": "SUM(Revenue_TW)"
    })

# 3. Share_Pct for top entities
for idx, row in top_entities.iterrows():
    if pd.notna(row['Share_Pct']):
        facts.append({
            "entity": row['Entity'],
            "metric": "share",
            "period": "TW",
            "value": round(to_python(row['Share_Pct']), 1),
            "formula": "Share_Pct"
        })

# 4. Rank for top entities
for idx, row in top_entities.iterrows():
    if pd.notna(row['Rank']):
        facts.append({
            "entity": row['Entity'],
            "metric": "rank",
            "period": "TW",
            "value": int(to_python(row['Rank'])),
            "formula": "Rank"
        })

# 5. Units_TW for top entities
for idx, row in top_entities.iterrows():
    if pd.notna(row['Units_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "units",
            "period": "TW",
            "value": int(to_python(row['Units_TW'])),
            "formula": "Units_TW"
        })

# 6. Orders_TW for top entities
for idx, row in top_entities.iterrows():
    if pd.notna(row['Orders_TW']):
        facts.append({
            "entity": row['Entity'],
            "metric": "orders",
            "period": "TW",
            "value": int(to_python(row['Orders_TW'])),
            "formula": "Orders_TW"
        })

# 7. WoW_Pct for top entities
for idx, row in top_entities.iterrows():
    if pd.notna(row['WoW_Pct']):
        facts.append({
            "entity": row['Entity'],
            "metric": "revenue",
            "period": "WoW",
            "value": round(to_python(row['WoW_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LW) / Revenue_LW * 100"
        })

# 8. YoY_Pct for top entities
for idx, row in top_entities.iterrows():
    if pd.notna(row['YoY_Pct']):
        facts.append({
            "entity": row['Entity'],
            "metric": "revenue",
            "period": "YoY",
            "value": round(to_python(row['YoY_Pct']), 1),
            "formula": "(Revenue_TW - Revenue_LY) / Revenue_LY * 100"
        })

# 9. Total Units_TW
total_units_tw = df['Units_TW'].sum()
if pd.notna(total_units_tw) and total_units_tw > 0:
    facts.append({
        "entity": "TOTAL",
        "metric": "units",
        "period": "TW",
        "value": int(to_python(total_units_tw)),
        "formula": "SUM(Units_TW)"
    })

# 10. Total Orders_TW
total_orders_tw = df['Orders_TW'].sum()
if pd.notna(total_orders_tw) and total_orders_tw > 0:
    facts.append({
        "entity": "TOTAL",
        "metric": "orders",
        "period": "TW",
        "value": int(to_python(total_orders_tw)),
        "formula": "SUM(Orders_TW)"
    })

# Limit to 25 facts
facts = facts[:25]

print(json.dumps(facts))
